[["NOT_MIGRATED", aggregate.not_migrated_rows], ["USAGE_UNKNOWN", aggregate.usage_unknown_rows], ["PRICE_MISSING", aggregate.price_missing_rows], ["CURRENCY_MISSING", aggregate.currency_missing_rows],
// 信息项：依据待核实行数，不影响 completeness。
