/**
 * API 费用估算统一聚合入口（WP1 C1 / task 2.1）。
 *
 * 依据：OpenSpec change simplify-api-cost-and-official-balance
 *   - specs/api-cost-estimation ACE-02/03/04/07（同源估算、不依赖余额与资金初始化、
 *     保留未知与已知部分、币种分列）；
 *   - WP0 contracts.md §1 C1（scope/period/amounts/completeness/gap/price_basis）；
 *   - WP1 plan.md §4 决策 2/3（聚合语义、缺口原因、处置排除、PRICE_BASIS_UNVERIFIED）。
 *
 * 语义合同（S1 §3.3，照做不另行发明）：
 *   - 只查 ledger_line 且 resource_mode='API'；禁止 JOIN 资金表/快照表/候选表；
 *     不 JOIN billing_rule：价格依据读请求时冻结的 ledger_line.billing_rule_snapshot
 *     ->>'sourceStatus'（F3/ACE-02：事后修改规则不得改变历史请求的价格依据；
 *     快照缺失该键的旧行回退 UNVERIFIED——缺证据即待核实，不把现值冒充当时值）。
 *   - 行分类（互斥）：
 *     1) 明确零：api_cost_status='CONFIRMED_ZERO_NO_UPSTREAM'（0 贡献、不算缺口；
 *        0085 shape 约束保证该状态行 api_cost=0 非空，天然不落入缺口判定）；
 *     2) 处置排除：api_cost IS NULL 且 effectiveUsageCostDispositionSql 为真
 *        （0 贡献、不算缺口、计入 excludedNoRecordedCost）；
 *     3) 已计价金额行：api_cost IS NOT NULL（金额取 effectiveReportedApiCostSql，
 *        处置投影权威口径；按 api_cost_currency 分桶求和；币种 NULL 的已计价行
 *        不入桶、计 CURRENCY_MISSING 缺口）；
 *     4) 缺口行：api_cost IS NULL 且未处置排除（非 CONFIRMED_ZERO 由 shape 约束保证）：
 *        api_cost_status='NOT_MIGRATED' → NOT_MIGRATED；否则 usage_quality='UNKNOWN' →
 *        USAGE_UNKNOWN；否则 → PRICE_MISSING（用量已知缺价格）。
 *   - completeness：存在任一缺口行 → KNOWN_PARTIAL；期间无任何 API 行 → KNOWN_COMPLETE +
 *     空 amounts；无缺口且无已计价金额行（只剩明确零/处置排除）→ ZERO_CONFIRMED；
 *     否则 KNOWN_COMPLETE。
 *   - gaps 另含信息项 PRICE_BASIS_UNVERIFIED（按快照冻结 sourceStatus='UNVERIFIED'
 *     计价的行数；旧行快照无键按 UNVERIFIED 计；不影响 completeness；
 *     CONFIRMED_ZERO_NO_UPSTREAM 行不计——零确认行无价格依据语义，恒快照 NULL，
 *     不排除会误报依据待核实，与 priced_rows 口径对齐，R4 总指挥裁定项）。
 *   - priceBasis：期间内计价行（api_cost IS NOT NULL）涉及的 billing_rule_id/rule_version
 *     及请求时冻结的快照 sourceStatus（同一规则不同行可能冻结不同状态，各自成行）。
 *   - 期间过滤：settled_at >= start AND settled_at < end（与 dashboard-home-costs.ts
 *     loadWindowOperatingFinance 同口径）。
 *   - 金额一律 decimal.js（Money/money，八位小数字符串），禁止 float。
 *
 * W20-10（R2 性能修复）：新增 loadApiCostEstimationByResource 批量分组入口——与
 * loadApiCostEstimation 完全同源（同 estimationLinesSql、同聚合计数/币种求和投影与
 * priceBasis DISTINCT 三元组片段、同 assembleApiCostEstimation 派生），仅追加
 * provider_resource_id 分组维度，供 resource-insights/query.ts 一次读取取代逐资源
 * N+1 调用；批量版三条聚合折入单条语句（ledger_line 基表只扫一遍，见其注释），
 * 单资源语义零改动。
 */
import { sql, type Kysely } from "kysely";
import type { Database } from "../kysely.js";
import { money } from "./provider-finance-core.js";
import { effectiveUsageCostDispositionSql } from "./provider-finance-usage-dispositions.js";
import { effectiveReportedApiCostSql } from "./usage-cost-disposition-projection.js";

export type ApiCostEstimationCompleteness =
  | "KNOWN_COMPLETE"
  | "KNOWN_PARTIAL"
  | "ZERO_CONFIRMED";

export type ApiCostEstimationGapReason =
  | "NOT_MIGRATED"
  | "USAGE_UNKNOWN"
  | "PRICE_MISSING"
  | "CURRENCY_MISSING"
  | "PRICE_BASIS_UNVERIFIED";

export type BillingRuleSourceStatus = "VERIFIED" | "UNVERIFIED";

export interface ApiCostEstimationAmount {
  currency: string;
  /** 八位小数字符串（decimal.js，禁止 float）。 */
  amount: string;
}

export interface ApiCostEstimationGap {
  reason: ApiCostEstimationGapReason;
  count: number;
}

export interface ApiCostEstimationPriceBasis {
  ruleId: string;
  /** ledger_line 冻结的版本；历史行可能为 null。 */
  ruleVersion: string | null;
  /** ledger_line.billing_rule_snapshot 冻结的请求时值；旧行快照无该键为 UNVERIFIED（F3）。 */
  sourceStatus: BillingRuleSourceStatus;
}

export interface ApiCostEstimation {
  scope: { enterpriseId: string; resourceIds: string[] | null };
  period: { start: Date; end: Date };
  amounts: ApiCostEstimationAmount[];
  completeness: ApiCostEstimationCompleteness;
  gaps: ApiCostEstimationGap[];
  priceBasis: ApiCostEstimationPriceBasis[];
  excludedNoRecordedCost: number;
}

export interface ApiCostEstimationQuery {
  start: Date;
  /** 半开区间 [start, end)。 */
  end: Date;
  /** 可选资源过滤；缺省/null＝全企业。空数组＝空结果（原样透传，不展开为全量）。 */
  resourceIds?: string[];
}

export interface ApiCostEstimationBatchQuery {
  start: Date;
  /** 半开区间 [start, end)。 */
  end: Date;
  /** 资源清单；空数组＝空 Map（调用方无 API 资源时与逐资源循环空集同语义）。 */
  resourceIds: string[];
}

interface EstimateAggregateRow {
  total_rows: number;
  priced_rows: number;
  confirmed_zero_rows: number;
  excluded_rows: number;
  currency_missing_rows: number;
  not_migrated_rows: number;
  usage_unknown_rows: number;
  price_missing_rows: number;
  basis_unverified_rows: number;
}

interface EstimateAmountRow {
  currency: string;
  amount: string;
}

interface EstimatePriceBasisRow {
  rule_id: string;
  rule_version: string | null;
  source_status: string;
}

/**
 * 批量折单语句的 jsonb 载荷行（node-postgres 默认解析 jsonb → JS 对象数组，
 * 键名与 EstimateAmountRow / EstimatePriceBasisRow 字段一一对应，无需二次转换）。
 */
interface EstimateBatchAmountJson {
  currency: string;
  amount: string;
}

interface EstimateBatchPriceBasisJson {
  rule_id: string;
  rule_version: string | null;
  source_status: string;
}

/** 批量折单语句结果行：每请求资源恰好一行（聚合计数＋jsonb 金额分桶＋jsonb 价格依据）。 */
interface EstimateBatchResourceRow extends EstimateAggregateRow {
  provider_resource_id: string;
  amounts: EstimateBatchAmountJson[];
  basis: EstimateBatchPriceBasisJson[];
}

/**
 * 期间内本企业 API 账本行的分类投影（与两条聚合查询共用，保证口径一致）。
 * includeResourceId 仅供批量分组版（loadApiCostEstimationByResource）追加
 * provider_resource_id 分组维度；单资源版缺省 false，生成 SQL 与原版逐字一致。
 */
function estimationLinesSql(
  enterpriseId: string,
  start: Date,
  end: Date,
  resourceIds: string[] | null,
  includeResourceId = false,
) {
  const scopeFilter = resourceIds === null
    ? sql`TRUE`
    : sql`l.provider_resource_id = ANY(${resourceIds}::uuid[])`;
  const resourceColumn = includeResourceId
    ? sql`l.provider_resource_id,`
    : sql``;
  return sql`
    SELECT ${resourceColumn}
           l.api_cost, l.api_cost_currency, l.api_cost_status, l.usage_quality,
           l.billing_rule_id, l.rule_version,
           coalesce(l.billing_rule_snapshot->>'sourceStatus', 'UNVERIFIED')
             AS rule_source_status,
           ${effectiveUsageCostDispositionSql("l")} AS excluded,
           ${effectiveReportedApiCostSql("l")} AS reported_cost
      FROM ledger_line l
     WHERE l.enterprise_id = ${enterpriseId}::uuid
       AND l.resource_mode = 'API'
       AND l.settled_at >= ${start} AND l.settled_at < ${end}
       AND ${scopeFilter}
  `;
}

/** 聚合一共用：分类计数投影（单资源版与批量分组版同源，W20-10 提取，逐字未改）。 */
const ESTIMATE_COUNT_PROJECTION = sql`
  count(*)::int AS total_rows,
  count(*) FILTER (WHERE lines.api_cost IS NOT NULL
    AND coalesce(lines.api_cost_status,'') <> 'CONFIRMED_ZERO_NO_UPSTREAM')::int AS priced_rows,
  count(*) FILTER (WHERE lines.api_cost_status = 'CONFIRMED_ZERO_NO_UPSTREAM')::int AS confirmed_zero_rows,
  count(*) FILTER (WHERE lines.api_cost IS NULL AND lines.excluded)::int AS excluded_rows,
  count(*) FILTER (WHERE lines.api_cost IS NOT NULL
    AND coalesce(lines.api_cost_status,'') <> 'CONFIRMED_ZERO_NO_UPSTREAM'
    AND lines.api_cost_currency IS NULL)::int AS currency_missing_rows,
  count(*) FILTER (WHERE lines.api_cost IS NULL AND NOT lines.excluded
    AND lines.api_cost_status = 'NOT_MIGRATED')::int AS not_migrated_rows,
  count(*) FILTER (WHERE lines.api_cost IS NULL AND NOT lines.excluded
    AND coalesce(lines.api_cost_status,'') <> 'NOT_MIGRATED'
    AND lines.usage_quality = 'UNKNOWN')::int AS usage_unknown_rows,
  count(*) FILTER (WHERE lines.api_cost IS NULL AND NOT lines.excluded
    AND coalesce(lines.api_cost_status,'') <> 'NOT_MIGRATED'
    AND lines.usage_quality <> 'UNKNOWN')::int AS price_missing_rows,
  count(*) FILTER (WHERE lines.api_cost IS NOT NULL
    AND coalesce(lines.api_cost_status,'') <> 'CONFIRMED_ZERO_NO_UPSTREAM'
    AND lines.rule_source_status = 'UNVERIFIED')::int AS basis_unverified_rows
`;

/** 聚合二共用：已计价行按币种求和投影（单资源版与批量分组版同源，W20-10 提取，逐字未改）。 */
const ESTIMATE_PRICED_SUM = sql`
  coalesce(sum(lines.reported_cost) FILTER (WHERE lines.api_cost IS NOT NULL
      AND coalesce(lines.api_cost_status,'') <> 'CONFIRMED_ZERO_NO_UPSTREAM'), 0
  )::numeric(30,8)::text
`;

/**
 * 期间零行的资源条目（批量版）＝单资源版空期间聚合（count(*) 空集恒 0）。
 * 折单语句已由 unnest 驱动＋coalesce 直接为期间零行资源物化同值行；此处仅作
 * TS 侧缺行纯防御回退（与折单前 `?? EMPTY_ESTIMATE_AGGREGATE` 行为一致）。
 */
const EMPTY_ESTIMATE_AGGREGATE: EstimateAggregateRow = {
  total_rows: 0,
  priced_rows: 0,
  confirmed_zero_rows: 0,
  excluded_rows: 0,
  currency_missing_rows: 0,
  not_migrated_rows: 0,
  usage_unknown_rows: 0,
  price_missing_rows: 0,
  basis_unverified_rows: 0,
};

/**
 * 聚合行 → Estimation 的派生（单资源版与批量分组版共用；W20-10 提取，逻辑逐字未改）。
 * scope 由调用方给：单资源版透传查询 resourceIds（null＝全企业），批量版每资源 [id]。
 */
function assembleApiCostEstimation(
  enterpriseId: string,
  scopeResourceIds: string[] | null,
  start: Date,
  end: Date,
  aggregate: EstimateAggregateRow,
  amountRows: EstimateAmountRow[],
  basisRows: EstimatePriceBasisRow[],
): ApiCostEstimation {
  const gapTotal = aggregate.not_migrated_rows + aggregate.usage_unknown_rows
    + aggregate.price_missing_rows + aggregate.currency_missing_rows;
  // 语义（S1 §3.3）：缺口>0 → KNOWN_PARTIAL；期间无任何 API 行 → KNOWN_COMPLETE（空 amounts）；
  // 无缺口且无已计价金额行（只剩明确零/处置排除）→ ZERO_CONFIRMED；否则 KNOWN_COMPLETE。
  const completeness: ApiCostEstimationCompleteness = gapTotal > 0
    ? "KNOWN_PARTIAL"
    : aggregate.total_rows === 0 || aggregate.priced_rows > 0
      ? "KNOWN_COMPLETE"
      : "ZERO_CONFIRMED";

  const gaps: ApiCostEstimationGap[] = ([
    ["NOT_MIGRATED", aggregate.not_migrated_rows],
    ["USAGE_UNKNOWN", aggregate.usage_unknown_rows],
    ["PRICE_MISSING", aggregate.price_missing_rows],
    ["CURRENCY_MISSING", aggregate.currency_missing_rows],
    // 信息项：依据待核实行数，不影响 completeness。
    ["PRICE_BASIS_UNVERIFIED", aggregate.basis_unverified_rows],
  ] as const)
    .filter(([, count]) => count > 0)
    .map(([reason, count]) => ({ reason, count }));

  return {
    scope: { enterpriseId, resourceIds: scopeResourceIds },
    period: { start, end },
    amounts: amountRows.map((row) => ({
      currency: row.currency,
      amount: money(row.amount),
    })),
    completeness,
    gaps,
    priceBasis: basisRows.map((row) => ({
      ruleId: row.rule_id,
      ruleVersion: row.rule_version,
      sourceStatus: row.source_status as BillingRuleSourceStatus,
    })),
    excludedNoRecordedCost: aggregate.excluded_rows,
  };
}

/**
 * 统一聚合入口：同源 API 费用估算（不依赖资金账户/期初/余额差）。
 * 三条聚合查询读同一批账本行；与 loadWindowOperatingFinance 一致不做显式事务。
 */
export async function loadApiCostEstimation(
  db: Kysely<Database>,
  enterpriseId: string,
  query: ApiCostEstimationQuery,
): Promise<ApiCostEstimation> {
  const { start, end } = query;
  const resourceIds = query.resourceIds ?? null;
  const [aggregates, amountRows, basisRows] = await Promise.all([
    sql<EstimateAggregateRow>`
      WITH lines AS (${estimationLinesSql(enterpriseId, start, end, resourceIds)})
      SELECT ${ESTIMATE_COUNT_PROJECTION}
      FROM lines
    `.execute(db),
    sql<EstimateAmountRow>`
      WITH lines AS (${estimationLinesSql(enterpriseId, start, end, resourceIds)})
      SELECT lines.api_cost_currency AS currency,
        ${ESTIMATE_PRICED_SUM} AS amount
      FROM lines
      WHERE lines.api_cost_currency IS NOT NULL
      GROUP BY lines.api_cost_currency
      ORDER BY lines.api_cost_currency ASC
    `.execute(db),
    sql<EstimatePriceBasisRow>`
      WITH lines AS (${estimationLinesSql(enterpriseId, start, end, resourceIds)})
      SELECT DISTINCT lines.billing_rule_id AS rule_id, lines.rule_version,
             lines.rule_source_status AS source_status
      FROM lines
      WHERE lines.api_cost IS NOT NULL AND lines.billing_rule_id IS NOT NULL
      ORDER BY lines.billing_rule_id ASC, lines.rule_version ASC NULLS LAST
    `.execute(db),
  ]);

  // count(*) 聚合恒返回一行（空集为 0），缺行只能是驱动层异常。
  const a = aggregates.rows[0]
    ?? (() => { throw new Error("api_cost_estimation_aggregate_row_missing"); })();
  return assembleApiCostEstimation(
    enterpriseId, resourceIds, start, end, a, amountRows.rows, basisRows.rows,
  );
}

/**
 * 批量分组入口（W20-10）：一次调用取代逐资源 loadApiCostEstimation（N+1 已由 R2 消除，
 * 每资源 3 条 → 恒 3 条；残余瓶颈是三条独立语句各自 `WITH lines AS (estimationLinesSql)`
 * ——ledger_line 基表（百万行）与处置判定函数被完整扫描/执行三遍，W20-10
 * resourceUtilizationP95 稳定超标）。本版把三条折成**单条语句**：
 *
 * 单次基表扫描的实现：
 *   - `lines` CTE（同一 estimationLinesSql，含 provider_resource_id 分组列）被下方
 *     counts/amounts/basis 三个子聚合多处引用——PG 对多引用 CTE 物化一次（显式
 *     MATERIALIZED 锁定该语义），基表扫描与处置判定只执行一遍；
 *   - 主查询以 unnest(去重资源清单) WITH ORDINALITY 为驱动 LEFT JOIN 三子聚合，
 *     按 provider_resource_id 汇成单结果集，ORDER BY ids.ordinality 保持请求清单同序。
 *
 * 与三条语句版（及单资源版）的逐字段等价性依据：
 *   - counts：ESTIMATE_COUNT_PROJECTION 逐字嵌入，GROUP BY provider_resource_id
 *     （＝折单前聚合一）；
 *   - amounts：内层子查询与折单前聚合二逐字同源（GROUP BY 资源+币种、
 *     ESTIMATE_PRICED_SUM、WHERE api_cost_currency IS NOT NULL），外层
 *     jsonb_agg ORDER BY currency ASC 还原「资源内按币种 ASC」数组顺序，
 *     jsonb_build_object 键名与 EstimateAmountRow 字段一致（currency/amount 均非 NULL）；
 *   - basis：内层子查询与折单前聚合三逐字同源（DISTINCT 资源+rule_id+rule_version+
 *     source_status 四元组），外层 jsonb_agg ORDER BY rule_id ASC, rule_version ASC
 *     NULLS LAST 还原原排序（同一 rule_id+version 不同 source_status 的并列顺序
 *     两个版本同为未指定，天然一致）；
 *   - 期间零行资源：counts/amounts/basis 均无该资源行 → LEFT JOIN 置 NULL →
 *     coalesce 计数列 0（＝EMPTY_ESTIMATE_AGGREGATE）、amounts/basis '[]'::jsonb
 *     （＝折单前 TS 侧 `?? []`），与逐资源调用空期间语义逐字段一致；
 *   - jsonb 载荷由 node-postgres 默认解析为 JS 对象数组，键名即 TS 行字段，
 *     assembleApiCostEstimation 派生零改动。
 *
 * 输出合同不变：Map<resourceId, ApiCostEstimation>，每资源与逐资源调用
 * loadApiCostEstimation(db, ent, {start, end, resourceIds:[id]}) 返回值逐字段一致
 * （scope.resourceIds=[id]、period 同查询）。请求清单外的资源行不进入任何所请求资源
 * （scopeFilter 同前）。一致性回归：api-cost-estimation-by-resource.integration.test.ts
 * （多资源逐字段对照）。
 */
export async function loadApiCostEstimationByResource(
  db: Kysely<Database>,
  enterpriseId: string,
  query: ApiCostEstimationBatchQuery,
): Promise<Map<string, ApiCostEstimation>> {
  const { start, end } = query;
  // 清单去重（调用方来源为主键集合，正常无重复；防御性收敛，ANY/unnest 语义不变）。
  const resourceIds = [...new Set(query.resourceIds)];
  if (resourceIds.length === 0) return new Map();
  const batchRows = await sql<EstimateBatchResourceRow>`
    WITH lines AS MATERIALIZED (${estimationLinesSql(enterpriseId, start, end, resourceIds, true)}),
    counts AS (
      SELECT lines.provider_resource_id,
             ${ESTIMATE_COUNT_PROJECTION}
        FROM lines
       GROUP BY lines.provider_resource_id
    ),
    amounts AS (
      SELECT per_currency.provider_resource_id,
             jsonb_agg(jsonb_build_object(
               'currency', per_currency.currency, 'amount', per_currency.amount
             ) ORDER BY per_currency.currency ASC) AS amounts
        FROM (
          SELECT lines.provider_resource_id, lines.api_cost_currency AS currency,
                 ${ESTIMATE_PRICED_SUM} AS amount
            FROM lines
           WHERE lines.api_cost_currency IS NOT NULL
           GROUP BY lines.provider_resource_id, lines.api_cost_currency
        ) AS per_currency
       GROUP BY per_currency.provider_resource_id
    ),
    basis AS (
      SELECT distinct_basis.provider_resource_id,
             jsonb_agg(jsonb_build_object(
               'rule_id', distinct_basis.rule_id, 'rule_version', distinct_basis.rule_version,
               'source_status', distinct_basis.source_status
             ) ORDER BY distinct_basis.rule_id ASC,
               distinct_basis.rule_version ASC NULLS LAST) AS basis
        FROM (
          SELECT DISTINCT lines.provider_resource_id, lines.billing_rule_id AS rule_id,
                 lines.rule_version, lines.rule_source_status AS source_status
            FROM lines
           WHERE lines.api_cost IS NOT NULL AND lines.billing_rule_id IS NOT NULL
        ) AS distinct_basis
       GROUP BY distinct_basis.provider_resource_id
    )
    SELECT ids.provider_resource_id,
           coalesce(counts.total_rows, 0) AS total_rows,
           coalesce(counts.priced_rows, 0) AS priced_rows,
           coalesce(counts.confirmed_zero_rows, 0) AS confirmed_zero_rows,
           coalesce(counts.excluded_rows, 0) AS excluded_rows,
           coalesce(counts.currency_missing_rows, 0) AS currency_missing_rows,
           coalesce(counts.not_migrated_rows, 0) AS not_migrated_rows,
           coalesce(counts.usage_unknown_rows, 0) AS usage_unknown_rows,
           coalesce(counts.price_missing_rows, 0) AS price_missing_rows,
           coalesce(counts.basis_unverified_rows, 0) AS basis_unverified_rows,
           coalesce(amounts.amounts, '[]'::jsonb) AS amounts,
           coalesce(basis.basis, '[]'::jsonb) AS basis
    FROM unnest(${resourceIds}::uuid[]) WITH ORDINALITY AS ids(provider_resource_id, ordinality)
    LEFT JOIN counts ON counts.provider_resource_id = ids.provider_resource_id
    LEFT JOIN amounts ON amounts.provider_resource_id = ids.provider_resource_id
    LEFT JOIN basis ON basis.provider_resource_id = ids.provider_resource_id
    ORDER BY ids.ordinality ASC
  `.execute(db);
  const rowsByResource = new Map(
    batchRows.rows.map((row) => [row.provider_resource_id, row]),
  );
  const result = new Map<string, ApiCostEstimation>();
  for (const resourceId of resourceIds) {
    const row = rowsByResource.get(resourceId);
    result.set(resourceId, assembleApiCostEstimation(
      enterpriseId,
      [resourceId],
      start,
      end,
      // unnest 驱动保证每请求资源恰一行；缺行仅纯防御（与折单前回退一致）。
      row ?? EMPTY_ESTIMATE_AGGREGATE,
      row?.amounts ?? [],
      row?.basis ?? [],
    ));
  }
  return result;
}

src/repositories/official-balance-states.source:
/**
 * WP3 task 3.3 / C2 合同：官方余额状态读取（逐资源行，OAB-05 无任何合计）。
 *
 * 与既有读取的区别：快照侧显式按 design D2 双滤
 * `source='PROVIDER_SYNC' AND balance_source='PROVIDER_API'`（官方来源且确为
 * 余额 API 采集）——F1 返修（R2）补 balance_source 滤：HTTP 写旁路时代遗留的
 * `source='PROVIDER_SYNC'` 而 `balance_source=NULL` 的冒充行不再进入官方余额域。
 * `listLatestOperatingSnapshots` 不筛 source（ADMIN 手工会混入），其语义与
 * dashboard 等旧消费方不动；本函数是官方余额域的独立读取入口。
 *
 * status 为主状态（判定序见 statusMatrix），叠加语义由 `expired` /
 * `last_attempt_failed` 布尔承载（OAB-04：失败与过期可同时表达）。
 */
import { sql, type Kysely } from "kysely";
import { canonicalProviderCode } from "@qianliu/provider-adapters";
import type { Database } from "../kysely.js";

export type OfficialBalanceStatus =
  | "UNSUPPORTED" | "NEVER_SYNCED" | "OK" | "FAILED" | "EXPIRED" | "SYNCING";

export interface OfficialBalanceState {
  provider_resource_id: string;
  supported: boolean;
  status: OfficialBalanceStatus;
  /** OAB-04 叠加：最新成功快照 collected_at 距 now 超过 P2（对所有非 UNSUPPORTED 态计算）。 */
  expired: boolean;
  /** OAB-04 叠加：最新 attempt（任意 outcome）的 balance_status 为 FAILED。 */
  last_attempt_failed: boolean;
  total_balance: string | null;
  currency: string | null;
  composition: { granted: string | null; topped: string | null } | null;
  available: boolean | null;
  /** 最新成功（PROVIDER_SYNC）快照的采集时间；无成功快照 → null。 */
  last_success_at: Date | null;
  last_attempt: {
    at: Date;
    outcome: "SUCCESS" | "FAILED" | "NOT_SUPPORTED";
    reason: string | null;
  } | null;
  /** max(最近 attempt started_at + P3, RUNNING 租约 expires_at)；已过期/无值 → null（立即可刷）。 */
  next_refresh_at: Date | null;
}

export interface OfficialBalanceStatesInput {
  now: Date;
  /** P2 过期阈值（毫秒，readProviderOperatingBalanceExpireMs）。 */
  expireMs: number;
  /** P3 刷新冷却（毫秒，readProviderOperatingBalanceRefreshCooldownMs）。 */
  cooldownMs: number;
}

interface LatestOfficialSnapshotRow {
  provider_resource_id: string;
  current_balance: string | null;
  currency: string | null;
  granted_balance: string | null;
  topped_up_balance: string | null;
  provider_balance_available: boolean | null;
  collected_at: Date;
}

interface LatestAttemptRow {
  provider_resource_id: string;
  balance_status: "SUCCESS" | "FAILED" | "NOT_SUPPORTED";
  started_at: Date;
  completed_at: Date;
  failure_reason: string | null;
}

/**
 * status 派生矩阵（判定序）：
 * | # | 条件                                          | status       |
 * |---|-----------------------------------------------|--------------|
 * | 1 | canonical provider ≠ deepseek 或 mode ≠ API    | UNSUPPORTED  |
 * | 2 | 存在未过期 RUNNING 刷新租约（0096；F4 返修：expires_at 已过的 RUNNING 不再 SYNCING） | SYNCING |
 * | 3 | 无成功快照 ∧ 最新 attempt balance_status=FAILED | FAILED（余额 null，不显 0） |
 * | 4 | 无成功快照（含从未同步或仅 NOT_SUPPORTED 痕迹） | NEVER_SYNCED |
 * | 5 | 有成功快照 ∧ 最新 attempt FAILED               | FAILED（expired 可叠加 true） |
 * | 6 | 有成功快照 ∧ 最新 attempt 非 FAILED ∧ 超 P2     | EXPIRED      |
 * | 7 | 其余                                           | OK           |
 */

/**
 * status 主判定（判定序见上方矩阵）。F4 返修（R2）：租约过期的 RUNNING 刷新
 * 不再视为 SYNCING——回落快照/失败/NEVER_SYNCED 正常判定链；
 * next_refresh_at 的 now 过滤独立存在，不受影响。
 */
function deriveOfficialBalanceStatus(input: {
  supported: boolean;
  snapshot: LatestOfficialSnapshotRow | undefined;
  lastAttemptFailed: boolean;
  expired: boolean;
  refreshExpiresAt: Date | null;
  now: Date;
}): OfficialBalanceStatus {
  if (!input.supported) return "UNSUPPORTED";
  if (input.refreshExpiresAt !== null
      && input.refreshExpiresAt.getTime() > input.now.getTime()) return "SYNCING";
  if (!input.snapshot) return input.lastAttemptFailed ? "FAILED" : "NEVER_SYNCED";
  if (input.lastAttemptFailed) return "FAILED";
  if (input.expired) return "EXPIRED";
  return "OK";
}

export async function listOfficialBalanceStates(
  db: Kysely<Database>,
  enterpriseId: string,
  input: OfficialBalanceStatesInput,
): Promise<OfficialBalanceState[]> {
  const { now, expireMs, cooldownMs } = input;
  const [resources, snapshots, attempts, runningRefreshes] = await Promise.all([
    db.selectFrom("provider_resource")
      .innerJoin("provider", "provider.id", "provider_resource.provider_id")
      .select(["provider_resource.id", "provider_resource.mode", "provider.code as provider_code"])
      .where("provider_resource.enterprise_id", "=", enterpriseId)
      .where("provider.enterprise_id", "=", enterpriseId)
      .execute(),
    // 最新官方来源快照：DISTINCT ON + collected_at/version 倒序（与恢复链证据查询同序）。
    sql<LatestOfficialSnapshotRow>`
      SELECT DISTINCT ON (provider_resource_id)
        provider_resource_id, current_balance, currency, granted_balance,
        topped_up_balance, provider_balance_available, collected_at
      FROM provider_resource_operating_snapshot
      WHERE enterprise_id = ${enterpriseId}::uuid AND source = 'PROVIDER_SYNC'
        AND balance_source = 'PROVIDER_API'
      ORDER BY provider_resource_id, collected_at DESC, version DESC
    `.execute(db),
    sql<LatestAttemptRow>`
      SELECT DISTINCT ON (provider_resource_id)
        provider_resource_id, balance_status, started_at, completed_at, failure_reason
      FROM provider_resource_operating_sync_attempt
      WHERE enterprise_id = ${enterpriseId}::uuid
      ORDER BY provider_resource_id, started_at DESC, created_at DESC
    `.execute(db),
    db.selectFrom("provider_resource_balance_refresh")
      .select(["provider_resource_id", "expires_at"])
      .where("enterprise_id", "=", enterpriseId)
      .where("status", "=", "RUNNING")
      .execute(),
  ]);

  const snapshotByResource = new Map(
    snapshots.rows.map((row) => [row.provider_resource_id, row]),
  );
  const attemptByResource = new Map(
    attempts.rows.map((row) => [row.provider_resource_id, row]),
  );
  const refreshExpiryByResource = new Map(
    runningRefreshes.map((row) => [row.provider_resource_id, row.expires_at]),
  );

  const states = resources.map((resource) => {
    const supported = canonicalProviderCode(resource.provider_code) === "deepseek"
      && resource.mode === "API";
    const snapshot = snapshotByResource.get(resource.id);
    const attempt = attemptByResource.get(resource.id);
    const refreshExpiresAt = refreshExpiryByResource.get(resource.id) ?? null;
    const lastAttemptFailed = attempt?.balance_status === "FAILED";
    const expired = supported && snapshot !== undefined
      && now.getTime() - snapshot.collected_at.getTime() > expireMs;

    const status = deriveOfficialBalanceStatus({
      supported, snapshot, lastAttemptFailed, expired, refreshExpiresAt, now,
    });

    // next_refresh_at：max(最近 attempt started_at + P3, RUNNING 租约 expires_at)；
    // 已过去的候选不输出（立即可刷 → null）。
    const refreshCandidates: Date[] = [];
    if (attempt) {
      refreshCandidates.push(new Date(attempt.started_at.getTime() + cooldownMs));
    }
    if (refreshExpiresAt) refreshCandidates.push(refreshExpiresAt);
    const nextRefreshAtRaw = refreshCandidates.length > 0
      ? refreshCandidates.reduce((a, b) => (a.getTime() > b.getTime() ? a : b))
      : null;
    const nextRefreshAt = nextRefreshAtRaw !== null && nextRefreshAtRaw.getTime() > now.getTime()
      ? nextRefreshAtRaw
      : null;

    return {
      provider_resource_id: resource.id,
      supported,
      status,
      expired,
      last_attempt_failed: lastAttemptFailed,
      // 官方余额只来自 PROVIDER_SYNC 快照；不支持/无成功快照一律 null，绝不零值冒充
      // （ADMIN 手工金额不混入，OAB-01/OAB-02）。
      total_balance: supported && snapshot ? snapshot.current_balance : null,
      currency: supported && snapshot ? snapshot.currency : null,
      composition: supported && snapshot
        ? { granted: snapshot.granted_balance, topped: snapshot.topped_up_balance }
        : null,
      available: supported && snapshot ? snapshot.provider_balance_available : null,
      last_success_at: supported && snapshot ? snapshot.collected_at : null,
      last_attempt: supported && attempt
        ? {
            at: attempt.completed_at,
            outcome: attempt.balance_status,
            reason: attempt.failure_reason,
          }
        : null,
      next_refresh_at: supported ? nextRefreshAt : null,
    };
  });
  states.sort((a, b) => a.provider_resource_id.localeCompare(b.provider_resource_id));
  return states;
}

src/repositories/api-cost-estimation.fal.source:
/**
 * EG-02（gate-supplement run2）定向补充：api-cost-estimation 防御回退分支的最小
 * 单元覆盖（不触数据库，stub 驱动）。
 *
 * 覆盖合同明文的防御语义（与折单前行为一致的回退，不另发明行为）：
 *   - loadApiCostEstimation：count(*) 聚合恒返回一行（空集为 0），缺行只能是驱动层
 *     异常 → api_cost_estimation_aggregate_row_missing（L326-327 防御 throw）；
 *   - loadApiCostEstimationByResource：unnest 驱动保证每请求资源恰一行；缺行 →
 *     EMPTY_ESTIMATE_AGGREGATE / amounts '[]' / basis '[]' 等价回退（L445-447）；
 *   - 批量入口空清单 → 空 Map（L377）与清单去重（L376 Set）。
 */
import { describe, expect, it } from "vitest";
import type { Kysely } from "kysely";
import type { Database } from "../kysely.js";
import { loadApiCostEstimation, loadApiCostEstimationByResource } from "./api-cost-estimation.js";

/** 最小驱动 stub：sql``.execute(db) 一律返回给定行集（绕过真实连接）。 */
function stubDb(rows: unknown[]): Kysely<Database> {
  // sql``.execute(db) 调 db.getExecutor() 取执行器，再 transformQuery → compileQuery
  // → executeQuery（与 kysely RawBuilder #getExecutor/#compile 契约一致）。
  return {
    getExecutor: () => ({
      transformQuery: (node: unknown) => node,
      compileQuery: (node: unknown) => node,
      executeQuery: async () => ({ rows }),
    }),
  } as unknown as Kysely<Database>;
}

const start = new Date("2026-09-01T00:00:00+08:00");
const end = new Date("2026-10-01T00:00:00+08:00");

describe("api-cost-estimation 防御回退（EG-02 定向）", () => {
  it("单资源版：聚合行缺失（驱动层异常）→ api_cost_estimation_aggregate_row_missing", async () => {
    const db = stubDb([]);
    await expect(loadApiCostEstimation(db, "00000000-0000-0000-0000-000000000001", {
      start, end,
    })).rejects.toThrow("api_cost_estimation_aggregate_row_missing");
  });

  it("批量版：驱动行缺失 → 每请求资源回退 EMPTY_ESTIMATE_AGGREGATE＋空 amounts/basis", async () => {
    const db = stubDb([]);
    const idA = "00000000-0000-0000-0000-00000000000a";
    const result = await loadApiCostEstimationByResource(db, "00000000-0000-0000-0000-000000000001", {
      start, end, resourceIds: [idA],
    });
    expect(result.size).toBe(1);
    const estimation = result.get(idA);
    expect(estimation).toBeDefined();
    expect(estimation!.scope).toEqual({
      enterpriseId: "00000000-0000-0000-0000-000000000001", resourceIds: [idA],
    });
    expect(estimation!.period).toEqual({ start, end });
    // 空聚合 = 期间无任何 API 行 → KNOWN_COMPLETE＋空 amounts，与逐资源空期间同语义。
    expect(estimation!.completeness).toBe("KNOWN_COMPLETE");
    expect(estimation!.amounts).toEqual([]);
    expect(estimation!.gaps).toEqual([]);
    expect(estimation!.priceBasis).toEqual([]);
    expect(estimation!.excludedNoRecordedCost).toBe(0);
  });

  it("批量版：空清单 → 空 Map；重复清单去重为单条目", async () => {
    const emptyDb = stubDb([]);
    const idA = "00000000-0000-0000-0000-00000000000a";
    await expect(loadApiCostEstimationByResource(emptyDb, "00000000-0000-0000-0000-000000000001", {
      start, end, resourceIds: [],
    })).resolves.toEqual(new Map());

    // 去重后 unnest 只驱动一次；缺行回退使重复 id 仍映射到同一 EMPTY 估计。
    const result = await loadApiCostEstimationByResource(emptyDb, "00000000-0000-0000-0000-000000000001", {
      start, end, resourceIds: [idA, idA],
    });
    expect(result.size).toBe(1);
    expect(result.get(idA)!.completeness).toBe("KNOWN_COMPLETE");
  });
});

src/__tests-integration__/api-cost-estim.source:
/**
 * API 费用估算统一聚合入口集成测试（WP1 C1 / S1 合同 §5）。
 *
 * 覆盖：
 *   a) 无任何资金表数据（不建 provider_finance_event/快照/期初）的企业，已计价行 →
 *      amounts 正常产出（ACE-03 / AT-ACE-05 服务层核心）；
 *   b) 1 CNY + 2 USD 分列，两桶分别正确，绝不混币相加（ACE-07）；
 *   c) 已计价 1+2 元 + 用量已知缺价格行 → amounts=[3 CNY] + KNOWN_PARTIAL + PRICE_MISSING=1
 *      （F02 / ACE-04 场景 1）；
 *   c2) F2/ACE-04（返修轮 R4）：缺「适用分项」价行（结算 UNKNOWN_COST＋快照冻结缺失
 *      分项价）→ PRICE_MISSING、已知部分金额不含该行（不再补零 0.00044000）、
 *      api_cost NULL 行不进 priceBasis；
 *   d) 仅 CONFIRMED_ZERO_NO_UPSTREAM → ZERO_CONFIRMED、无缺口（ACE-04 场景 2）；
 *   e) 处置排除行 → excludedNoRecordedCost=1、无该缺口、金额不变（ACE-05 场景 2 前提）；
 *   f) price_basis 含 ruleId/ruleVersion/sourceStatus；UNVERIFIED 计价行触发
 *      PRICE_BASIS_UNVERIFIED 计数且不影响 completeness；
 *   g) 迁移 0093：billing_rule.source_status 存在、存量默认 UNVERIFIED、CHECK 拒绝非法值、
 *      down 可回滚、重放后数据保留；
 *   h) G3/AT-ACE-03（F11 雏形）：同企业价格版本 A/B 以 effective_from 为明确生效点，
 *      生效点前后各一笔消费按各自生效时点版本计价；不改动任何数据重读（模拟刷新页面）
 *      金额逐字不变；旧调用行保留版本 A、计价依据仍含版本 A（不重算）。
 *   i) F3/ACE-02 回归（R3）：价格依据读请求时冻结的快照 sourceStatus——事后改
 *      billing_rule.source_status 不改变历史请求的依据与金额；旧行快照缺
 *      sourceStatus 键回退 UNVERIFIED（不读当前规则现值）。
 * 另记录合同语义：期间无任何 API 行 → KNOWN_COMPLETE + 空 amounts（S1 §3.3）。
 */
import { createHash, randomUUID } from "node:crypto";
import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { sql } from "kysely";
import { startPostgresContainer, type PostgresTestInstance } from "@qianliu/testing";
import { createKysely, migrateToLatest, loadApiCostEstimation,
  type ApiCostEstimationGap } from "../index.js";
import { rollbackTo } from "./migration-rollback.js";

let pg: PostgresTestInstance;
let db: ReturnType<typeof createKysely>;
const start = new Date("2026-09-01T00:00:00+08:00");
const end = new Date("2026-10-01T00:00:00+08:00");

beforeAll(async () => {
  pg = await startPostgresContainer("api_cost_estimation");
  db = createKysely(pg.connectionString);
  await migrateToLatest(db);
}, 120_000);
afterAll(async () => { await db?.destroy(); await pg?.stop(); }, 60_000);

interface Fixture {
  enterpriseId: string;
  adminId: string;
  principalId: string;
  keyId: string;
  resourceId: string;
}

/** 每个场景独立企业；绝不写 provider_finance_event/快照/期初（ACE-03 核心前提）。 */
async function fixture(): Promise<Fixture> {
  const enterpriseId = randomUUID();
  const adminId = randomUUID();
  const principalId = randomUUID();
  const keyId = randomUUID();
  await db.insertInto("enterprise").values({ id: enterpriseId, name: "API 估算测试" }).execute();
  await db.insertInto("admin_user").values({
    id: adminId, enterprise_id: enterpriseId, username: adminId,
    password_hash: "not-used", status: "ACTIVE",
  }).execute();
  await db.insertInto("principal").values({
    id: principalId, enterprise_id: enterpriseId, type: "EMPLOYEE", name: "员工",
    person_id: null, owner_person_id: null, department_label: null,
    created_at: new Date("2026-08-01T00:00:00+08:00"),
  }).execute();
  await db.insertInto("principal_key").values({
    id: keyId, enterprise_id: enterpriseId, principal_id: principalId,
    key_prefix: "ql_test", key_digest: randomUUID(), allowed_model_ids: [],
  }).execute();
  const provider = await db.insertInto("provider").values({
    enterprise_id: enterpriseId, code: "deepseek", name: "DeepSeek",
    adapter_type: "OPENAI_COMPATIBLE",
  }).returning("id").executeTakeFirstOrThrow();
  const resource = await db.insertInto("provider_resource").values({
    enterprise_id: enterpriseId, provider_id: provider.id, name: "api 资源", mode: "API",
    credential_type: "API_KEY", created_at: new Date("2026-08-01T00:00:00+08:00"),
  }).returning("id").executeTakeFirstOrThrow();
  return { enterpriseId, adminId, principalId, keyId, resourceId: resource.id };
}

async function seedRule(f: Fixture, sourceStatus: "VERIFIED" | "UNVERIFIED") {
  const rule = await db.insertInto("billing_rule").values({
    enterprise_id: f.enterpriseId, rule_type: "API_PRICE",
    rule_version: `v-${sourceStatus.toLowerCase()}-${randomUUID().slice(0, 8)}`,
    effective_from: new Date("2026-08-01T00:00:00+08:00"),
    cache_hit_price: "0.000001", cache_miss_price: "0.000002", output_price: "0.000004",
    currency: "CNY", priority: 10, source: "fixture", source_status: sourceStatus,
  }).returning(["id", "rule_version"]).executeTakeFirstOrThrow();
  return rule;
}

/**
 * G3/AT-ACE-03（F11 雏形）：带明确生效点（effective_from）的价格版本规则。
 * 与既有 seedRule 并存（后者固定 2026-08-01 生效、按 sourceStatus 命名版本），
 * 本助手供 A/B 双版本分界用例使用，不改动既有助手语义。
 */
async function seedRuleVersioned(
  f: Fixture,
  input: {
    ruleVersion: string;
    effectiveFrom: Date;
    /** 每百万 token 单价（decimal 字面值）。 */
    cacheMissPrice: string;
    outputPrice: string;
    sourceStatus?: "VERIFIED" | "UNVERIFIED";
  },
) {
  return db.insertInto("billing_rule").values({
    enterprise_id: f.enterpriseId, rule_type: "API_PRICE",
    rule_version: input.ruleVersion,
    effective_from: input.effectiveFrom,
    cache_hit_price: "0", cache_miss_price: input.cacheMissPrice, output_price: input.outputPrice,
    currency: "CNY", priority: 10, source: "fixture",
    source_status: input.sourceStatus ?? "VERIFIED",
  }).returning(["id", "rule_version"]).executeTakeFirstOrThrow();
}

interface SeedLineInput {
  at: Date;
  cost: string | null;
  currency?: string | null;
  status: "PRICED_USAGE" | "CONFIRMED_ZERO_NO_UPSTREAM" | "UNKNOWN_COST" | "NOT_MIGRATED";
  usageQuality?: string;
  rule?: { id: string; rule_version: string } | null;
  /** 生产结算链自 9bf1560 起在 ledger_line.billing_rule_snapshot 冻结含 sourceStatus 的
   *  规则快照；夹具按生产形态补齐（F3：估算依据读该冻结键）。 */
  snapshot?: Record<string, unknown> | null;
  resourceOverride?: string;
  /** G3/AT-ACE-03 专用：显式 token 用量（缺省保持既有 1000/100，不影响既有用例）。 */
  inputTokens?: bigint;
  outputTokens?: bigint;
}

async function seedLine(f: Fixture, input: SeedLineInput): Promise<{ id: string; requestId: string }> {
  const requestId = randomUUID();
  const resourceId = input.resourceOverride ?? f.resourceId;
  const at = input.at;
  await db.insertInto("ai_request").values({
    id: requestId, enterprise_id: f.enterpriseId, principal_id: f.principalId,
    principal_key_id: f.keyId, protocol: "chat", unified_model: "model",
    status: "SUCCEEDED", started_at: at, finished_at: at,
  }).execute();
  const attempt = await db.insertInto("upstream_attempt").values({
    enterprise_id: f.enterpriseId, ai_request_id: requestId, attempt_no: 1,
    provider_resource_id: resourceId, upstream_model: "model", http_status: 200,
    response_committed: true, finished_at: at,
  }).returning("id").executeTakeFirstOrThrow();
  const inputTokens = input.inputTokens ?? 1000n;
  const outputTokens = input.outputTokens ?? 100n;
  const usage = await db.insertInto("usage_event").values({
    enterprise_id: f.enterpriseId, ai_request_id: requestId, upstream_attempt_id: attempt.id,
    provider_resource_id: resourceId, input_tokens: inputTokens, output_tokens: outputTokens,
    cache_tokens: 0n, reasoning_tokens: 0n, usage_quality: input.usageQuality ?? "PROVIDER_REPORTED",
    dedup_key: requestId, created_at: at,
  }).returning("id").executeTakeFirstOrThrow();
  const line = await db.insertInto("ledger_line").values({
    enterprise_id: f.enterpriseId, ai_request_id: requestId, upstream_attempt_id: attempt.id,
    usage_event_id: usage.id, provider_resource_id: resourceId, principal_id: f.principalId,
    resource_mode: "API", raw_input_tokens: inputTokens, raw_output_tokens: outputTokens,
    raw_cache_tokens: 0n, raw_reasoning_tokens: 0n,
    api_cost: input.cost,
    // 0085 shape 约束：CONFIRMED_ZERO 行 api_cost=0 且币种必须为 NULL。
    api_cost_currency: (input.cost === null || input.currency === null)
      ? null : input.currency ?? "CNY",
    api_cost_status: input.status,
    usage_quality: input.usageQuality ?? "PROVIDER_REPORTED",
    settled_at: at, created_at: at,
    billing_rule_id: input.rule?.id ?? null,
    rule_version: input.rule?.rule_version ?? null,
    billing_rule_snapshot: input.snapshot ?? null,
  }).returning("id").executeTakeFirstOrThrow();
  return { id: line.id, requestId };
}

/** 0086 合法处置：冻结 to_jsonb(line)，仅对 UNKNOWN_COST 且无已记成本事实的行生效。 */
async function seedDisposition(f: Fixture, line: { id: string; requestId: string }) {
  const fact = await sql<{ fact: Record<string, unknown> }>`
    SELECT to_jsonb(line) AS fact FROM ledger_line line
    WHERE line.enterprise_id=${f.enterpriseId}::uuid AND line.id=${line.id}::uuid`.execute(db);
  await db.insertInto("provider_finance_usage_cost_disposition").values({
    enterprise_id: f.enterpriseId, provider_resource_id: f.resourceId,
    ledger_line_id: line.id, ai_request_id: line.requestId,
    decision: "EXCLUDE_NO_SERVER_COST",
    original_ledger_fact: fact.rows[0]!.fact,
    server_cost_evidence: { request: line.requestId, policy: "server-recorded-cost-only", recordedCost: null },
    reason: "Administrator directs this exact unpriced record to be excluded from internal accounting",
    evidence_ref: `fixture-decision:${line.id}`,
    decided_by_admin_user_id: f.adminId,
    idempotency_key: randomUUID(),
    request_hash: createHash("sha256").update(line.id).digest("hex"),
  }).execute();
}

function gapOf(gaps: ApiCostEstimationGap[], reason: ApiCostEstimationGap["reason"]): number {
  return gaps.find((gap) => gap.reason === reason)?.count ?? 0;
}

