    //   A 版价格 (600000×1 + 200000×2)/1e6 = 1.00000000；
    //   B 版价格 (600000×0.5 + 200000×1)/1e6 = 0.50000000。
    const usage = { inputTokens: 600000n, outputTokens: 200000n };
    const lineA = await seedLine(f, { at: new Date("2026-09-10T12:00:00+08:00"),
